const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  // A1 portrait dimensions at 150 DPI (good quality, manageable file size)
  const width = 2480;  // ~420mm at 150dpi
  const height = 3508; // ~594mm at 150dpi

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({
    viewport: { width, height },
    deviceScaleFactor: 1,
  });

  const htmlPath = path.resolve('/app/poster.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });

  // Wait for fonts and charts to render
  await page.waitForTimeout(4000);

  // Additional wait for any SVG/chart rendering
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(1000);

  // Ensure output dir exists
  const outDir = path.resolve('/app/output');
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

  await page.screenshot({
    path: path.join(outDir, 'final_poster.png'),
    type: 'png',
    fullPage: false,
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})();
EOF
